export type GraphEvidenceKind = typeof GraphEvidenceKind[keyof typeof GraphEvidenceKind];


export const GraphEvidenceKind = {
  'import-statement': 'import-statement',
  'call-site': 'call-site',
  'class-definition': 'class-definition',
  'interface-definition': 'interface-definition',
  jsdoc: 'jsdoc',
  heuristic: 'heuristic',
} as const;

/**
 * A single piece of evidence that justifies a graph entity or relationship
 */
export interface GraphEvidence {
  file: string;
  line?: number;
  column?: number;
  /** Source code snippet at the evidence location */
  snippet?: string;
  kind: GraphEvidenceKind;
}

/**
 * Provenance record for a graph entity or relationship. All fields are optional for backwards compatibility.
 */
export interface GraphProvenance {
  /** Broad extraction category: typescript-ast | python-ast | regex-fallback | manual | discovery-import | provenance-registry-import. Replaces the old `extractor` field. */
  sourceType?: string;
  /** Specific mechanism (e.g. ts-compiler-api, api-route-detection) */
  method?: string;
  extractedAt?: string;
  /** Source location records that justify this element */
  evidence?: GraphEvidence[];
}

/**
 * Typed relationship category for Knowledge Graph 2.0
 */
export type GraphEdgeType = typeof GraphEdgeType[keyof typeof GraphEdgeType];


export const GraphEdgeType = {
  imports: 'imports',
  calls: 'calls',
  extends: 'extends',
  implements: 'implements',
  uses: 'uses',
  emits: 'emits',
  observes: 'observes',
  produces: 'produces',
  depends_on: 'depends_on',
} as const;

export type GraphEntityMetadata = { [key: string]: unknown };

export interface GraphEntity {
  id: string;
  projectId: string;
  /** The scan job that produced this entity, if any */
  scanJobId?: string;
  type: EntityType;
  name: string;
  path?: string;
  metadata?: GraphEntityMetadata;
  /** Sub-kind within the entity type (e.g. arrow-function, class-method, decorator) */
  kind?: string;
  /** Extraction source — typescript-ast | python-ast | regex-fallback | manual */
  sourceType?: string;
  /** True when the entity has JSDoc, a docstring, or equivalent documentation */
  isDocumented?: boolean;
  /** Free-form semantic classification tags (e.g. auth, public-api, deprecated) */
  semanticTags?: string[];
  /** Short description from doc comment or declaration signature */
  description?: string;
  /**
     * Extraction confidence — 1.0 = AST certainty, 0.5 = heuristic, 0.0 = unknown
     * @minimum 0
     * @maximum 1
     */
  confidence?: number;
  /** Business domain (e.g. auth, payments, infra) */
  domain?: string;
  /** Lifecycle stage — stable | experimental | deprecated | internal */
  lifecycle?: string;
  provenance?: GraphProvenance;
  createdAt: string;
}

export type GraphRelationshipMetadata = { [key: string]: unknown };

export interface GraphRelationship {
  id: string;
  sourceId: string;
  targetId: string;
  /** Project this relationship belongs to (denormalised for efficient filtering) */
  projectId?: string;
  /** Raw relation string preserved from the extractor */
  relation: string;
  /** The scan job that produced this relationship, if any */
  scanJobId?: string;
  relationType?: GraphEdgeType;
  /** Fine-grained sub-classification (e.g. static-import, type-only-import) */
  relationSubtype?: string;
  /**
     * Edge weight for weighted graph algorithms (typically equals confidence)
     * @minimum 0
     * @maximum 1
     */
  weight?: number;
  /**
     * Extraction confidence [0,1] — lower values indicate heuristic inference
     * @minimum 0
     * @maximum 1
     */
  confidence?: number;
  /** True when inferred by heuristic rules rather than direct parse evidence */
  isHeuristic?: boolean;
  /** True when observed at runtime, not inferred by static analysis */
  isRuntimeObserved?: boolean;
  /** Structured evidence records that justify this relationship */
  evidenceJson?: GraphEvidence[];
  /** Number of evidence items (indexed separately for fast cardinality queries) */
  evidenceCount?: number;
  /** Human-readable summary of the evidence */
  evidenceSummary?: string;
  semanticTags?: string[];
  /** Which extractor produced this relationship */
  sourceType?: string;
  metadata?: GraphRelationshipMetadata;
  provenance?: GraphProvenance;
  createdAt: string;
}

